// Type definitions for digitalpaye-node

export interface DigitalPayeOptions {
  publicKey: string;
  secret: string;
  baseUrl?: string;
  timeout?: number;
}

export interface ApiResponse<T = any> {
  data: T;
  meta?: any;
  message?: string;
}

export class DigitalPayeError extends Error {
  code: string;
  status: number;
  details: any;
}

export interface QueryParams {
  page?: number;
  limit?: number;
  [key: string]: any;
}

declare class Auth {
  me(): Promise<ApiResponse>;
  refreshToken(): Promise<string>;
}

declare class Orders {
  list(params?: QueryParams): Promise<ApiResponse>;
  retrieve(reference: string): Promise<ApiResponse>;
  create(params: {
    currency: string;
    items: Array<{ name: string; sku?: string; quantity: number; unit_price: number }>;
    url_success?: string;
    url_error?: string;
    metadata?: Record<string, any>;
  }): Promise<ApiResponse>;
  cancel(reference: string): Promise<ApiResponse>;
  pay(reference: string, params: PayParams): Promise<ApiResponse>;
}

interface PayParams {
  operator_code: string;
  external_ref: string;
  otp?: string;
  payer?: Record<string, any>;
  payer_phone?: string;
  payer_phone_prefix?: string;
  payer_first_name?: string;
  payer_last_name?: string;
  payer_email?: string;
  customer_id?: string;
  success_url?: string;
  error_url?: string;
  [key: string]: any;
}

declare class Transactions {
  list(params?: QueryParams): Promise<ApiResponse>;
  retrieve(reference: string): Promise<ApiResponse>;
  status(reference: string): Promise<ApiResponse>;
  collect(params: {
    amount: number;
    currency: string;
    operator_code: string;
    external_ref: string;
    otp?: string;
    payer?: Record<string, any>;
    payer_phone?: string;
    payer_phone_prefix?: string;
    payer_first_name?: string;
    payer_last_name?: string;
    payer_email?: string;
    customer_id?: string;
    order_id?: string;
    success_url?: string;
    error_url?: string;
    note?: string;
  }): Promise<ApiResponse>;
}

declare class PaymentLinks {
  list(params?: QueryParams): Promise<ApiResponse>;
  create(params: {
    label: string;
    description?: string;
    amount: number;
    currency: string;
    link_type?: string;
    url_success?: string;
    url_error?: string;
    expires_at?: string;
  }): Promise<ApiResponse>;
  delete(token: string): Promise<ApiResponse>;
  pay(token: string, params: PayParams): Promise<ApiResponse>;
}

declare class Payouts {
  list(params?: QueryParams): Promise<ApiResponse>;
  retrieve(reference: string): Promise<ApiResponse>;
  status(reference: string): Promise<ApiResponse>;
  create(params: {
    amount: number;
    currency: string;
    operator_code: string;
    external_ref: string;
    recipient?: Record<string, any>;
    recipient_phone?: string;
    note?: string;
  }): Promise<ApiResponse>;
}

declare class Balance {
  retrieve(): Promise<ApiResponse>;
  history(params?: QueryParams): Promise<ApiResponse>;
}

declare class Operators {
  list(): Promise<ApiResponse>;
  countries(): Promise<ApiResponse>;
  retrieve(code: string): Promise<ApiResponse>;
}

declare class Customers {
  list(params?: QueryParams): Promise<ApiResponse>;
  retrieve(id: string): Promise<ApiResponse>;
  update(id: string, params: Record<string, any>): Promise<ApiResponse>;
  transactions(id: string, params?: QueryParams): Promise<ApiResponse>;
}

declare class Beneficiaries {
  list(params?: QueryParams): Promise<ApiResponse>;
  create(params: Record<string, any>): Promise<ApiResponse>;
  retrieve(id: string): Promise<ApiResponse>;
  update(id: string, params: Record<string, any>): Promise<ApiResponse>;
  delete(id: string): Promise<ApiResponse>;
  transactions(id: string, params?: QueryParams): Promise<ApiResponse>;
  favorite(id: string): Promise<ApiResponse>;
}

declare class Invoices {
  list(params?: QueryParams): Promise<ApiResponse>;
  create(params: Record<string, any>): Promise<ApiResponse>;
  retrieve(id: string): Promise<ApiResponse>;
  update(id: string, params: Record<string, any>): Promise<ApiResponse>;
  delete(id: string): Promise<ApiResponse>;
  send(id: string): Promise<ApiResponse>;
  pdfData(id: string): Promise<ApiResponse>;
}

declare class BulkTransfers {
  list(params?: QueryParams): Promise<ApiResponse>;
  create(params: Record<string, any>): Promise<ApiResponse>;
  retrieve(id: string): Promise<ApiResponse>;
  items(id: string, params?: QueryParams): Promise<ApiResponse>;
  process(id: string): Promise<ApiResponse>;
  delete(id: string): Promise<ApiResponse>;
}

declare class ScheduledTransfers {
  list(params?: QueryParams): Promise<ApiResponse>;
  create(params: Record<string, any>): Promise<ApiResponse>;
  retrieve(id: string): Promise<ApiResponse>;
  update(id: string, params: Record<string, any>): Promise<ApiResponse>;
  pause(id: string): Promise<ApiResponse>;
  resume(id: string): Promise<ApiResponse>;
  delete(id: string): Promise<ApiResponse>;
  runNow(id: string): Promise<ApiResponse>;
}

declare class Escrow {
  list(params?: QueryParams): Promise<ApiResponse>;
  create(params: Record<string, any>): Promise<ApiResponse>;
  retrieve(id: string): Promise<ApiResponse>;
  release(id: string, params: { release_code: string }): Promise<ApiResponse>;
  dispute(id: string, params: { reason: string }): Promise<ApiResponse>;
  cancel(id: string, params: { reason: string }): Promise<ApiResponse>;
}

declare class Contactless {
  list(params?: QueryParams): Promise<ApiResponse>;
  create(params: Record<string, any>): Promise<ApiResponse>;
  info(token: string): Promise<ApiResponse>;
  pay(token: string, params: Record<string, any>): Promise<ApiResponse>;
  delete(token: string): Promise<ApiResponse>;
}

export default class DigitalPaye {
  constructor(options: DigitalPayeOptions);
  auth: Auth;
  orders: Orders;
  transactions: Transactions;
  paymentLinks: PaymentLinks;
  payouts: Payouts;
  balance: Balance;
  operators: Operators;
  customers: Customers;
  beneficiaries: Beneficiaries;
  invoices: Invoices;
  bulkTransfers: BulkTransfers;
  scheduledTransfers: ScheduledTransfers;
  escrow: Escrow;
  contactless: Contactless;
}
